import { currencySnapshotSchema, type CurrencyEntry, type CurrencySnapshot } from "@poe-odyssey/core";
import {
  ArrowDownUp,
  Clock3,
  ExternalLink,
  Heart,
  RefreshCw,
  Search,
  ShieldAlert,
  TrendingDown,
  TrendingUp
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { PageTitle } from "../App";

type SortKey = "value" | "volume" | "trend" | "name";

function trendOf(entry: CurrencyEntry): number | null {
  const values = entry.history
    .map((point) => point.chaosValue)
    .filter((value): value is number => value !== null && value > 0);
  if (values.length < 2) return null;
  return ((values.at(-1)! - values[0]!) / values[0]!) * 100;
}

function Sparkline({ entry }: { entry: CurrencyEntry }) {
  const points = entry.history
    .map((point) => point.chaosValue)
    .filter((value): value is number => value !== null);
  if (points.length < 2) return <span className="muted">資料累積中</span>;
  const min = Math.min(...points);
  const max = Math.max(...points);
  const range = max - min || 1;
  const path = points.map((value, index) => {
    const x = (index / (points.length - 1)) * 100;
    const y = 26 - ((value - min) / range) * 22;
    return `${index === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(" ");
  const trend = trendOf(entry) ?? 0;
  return (
    <svg className={`sparkline ${trend >= 0 ? "positive" : "negative"}`} viewBox="0 0 100 30" preserveAspectRatio="none" aria-label="七日趨勢">
      <path d={path} fill="none" stroke="currentColor" strokeWidth="2" vectorEffect="non-scaling-stroke" />
    </svg>
  );
}

export function MarketPage() {
  const [snapshot, setSnapshot] = useState<CurrencySnapshot>();
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");
  const [category, setCategory] = useState("全部");
  const [sort, setSort] = useState<SortKey>("value");
  const [favoritesOnly, setFavoritesOnly] = useState(false);
  const [favorites, setFavorites] = useState<string[]>(() => {
    try {
      return JSON.parse(localStorage.getItem("poe-odyssey-market-favorites") ?? "[]") as string[];
    } catch {
      return [];
    }
  });

  useEffect(() => {
    const controller = new AbortController();
    void fetch(`${import.meta.env.BASE_URL}data/market/snapshot.json`, {
      cache: "no-store",
      signal: controller.signal
    })
      .then(async (response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        setSnapshot(currencySnapshotSchema.parse(await response.json()));
      })
      .catch((reason: unknown) => {
        if ((reason as { name?: string }).name !== "AbortError") {
          setError(reason instanceof Error ? reason.message : "行情資料無法載入");
        }
      });
    return () => controller.abort();
  }, []);

  const categories = useMemo(() =>
    ["全部", ...new Set(snapshot?.entries.map((entry) => entry.category) ?? [])],
  [snapshot]);

  const entries = useMemo(() => {
    const query = search.trim().toLocaleLowerCase();
    return [...(snapshot?.entries ?? [])]
      .filter((entry) =>
        (category === "全部" || entry.category === category) &&
        (!favoritesOnly || favorites.includes(entry.id)) &&
        (!query || `${entry.name.zhTW} ${entry.name.en}`.toLocaleLowerCase().includes(query))
      )
      .sort((a, b) => {
        if (sort === "name") return a.name.zhTW.localeCompare(b.name.zhTW, "zh-TW");
        if (sort === "volume") return b.volume - a.volume;
        if (sort === "trend") return (trendOf(b) ?? -Infinity) - (trendOf(a) ?? -Infinity);
        return (b.chaosValue ?? -Infinity) - (a.chaosValue ?? -Infinity);
      });
  }, [category, favorites, favoritesOnly, search, snapshot, sort]);

  function toggleFavorite(id: string) {
    const next = favorites.includes(id)
      ? favorites.filter((favorite) => favorite !== id)
      : [...favorites, id];
    setFavorites(next);
    localStorage.setItem("poe-odyssey-market-favorites", JSON.stringify(next));
  }

  return (
    <div className="page market-page">
      <PageTitle
        eyebrow="CURRENCY MARKET · HOURLY HISTORY"
        title="通貨行情，一頁看懂"
        description="合法使用 GGG 公開 Currency Exchange 每小時歷史；提供搜尋、分類、收藏、成交量與七日趨勢。"
      >
        <a className="button primary" href="https://pathofexile.tw/trade/exchange/亡焰咒海" target="_blank" rel="noreferrer">
          台服官方市集 <ExternalLink size={16} />
        </a>
      </PageTitle>

      <div className="policy-banner market-policy">
        <ShieldAlert size={20} />
        <div>
          <strong>國際服官方歷史，不冒充台服即時價</strong>
          <p>{snapshot?.warning ?? "台服 Hotcool 未列入 GGG 公開 Currency Exchange API；PoeOdyssey 不呼叫或反向工程未公開端點。"}</p>
        </div>
      </div>

      <section className="market-toolbar panel">
        <label className="search-field">
          <Search size={17} />
          <input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="搜尋中文或英文名稱…" />
        </label>
        <label>
          <span>分類</span>
          <select value={category} onChange={(event) => setCategory(event.target.value)}>
            {categories.map((value) => <option key={value}>{value}</option>)}
          </select>
        </label>
        <label>
          <span><ArrowDownUp size={14} /> 排序</span>
          <select value={sort} onChange={(event) => setSort(event.target.value as SortKey)}>
            <option value="value">混沌價值</option>
            <option value="volume">成交量</option>
            <option value="trend">七日趨勢</option>
            <option value="name">名稱</option>
          </select>
        </label>
        <button className={`button ${favoritesOnly ? "primary" : "secondary"}`} onClick={() => setFavoritesOnly(!favoritesOnly)}>
          <Heart size={15} fill={favoritesOnly ? "currentColor" : "none"} /> 收藏
        </button>
      </section>

      {error && (
        <div className="error-card">
          <RefreshCw size={18} />
          <div><strong>行情快照無法載入</strong><p>{error}。攻略、PoB 與其他工具不受影響。</p></div>
        </div>
      )}

      <div className="market-meta">
        <span><Clock3 size={14} /> 更新：{snapshot ? new Date(snapshot.updatedAt).toLocaleString("zh-TW") : "載入中"}</span>
        <span>{snapshot?.league ?? "Allflame"} · {snapshot?.entries.length ?? 0} 種市場</span>
        <span>來源：{snapshot?.source.label ?? "GGG"}</span>
      </div>

      <section className="market-grid" aria-live="polite">
        {entries.map((entry) => {
          const trend = trendOf(entry);
          return (
            <article className="market-card" key={entry.id}>
              <button className={`favorite-button ${favorites.includes(entry.id) ? "active" : ""}`} onClick={() => toggleFavorite(entry.id)} aria-label={`收藏 ${entry.name.zhTW}`}>
                <Heart size={16} fill={favorites.includes(entry.id) ? "currentColor" : "none"} />
              </button>
              <div className="market-name">
                <span className="market-glyph">{entry.name.en.slice(0, 1)}</span>
                <div><h2>{entry.name.zhTW}</h2><small>{entry.name.en}</small></div>
              </div>
              <div className="market-price">
                <strong>{entry.chaosValue === null ? "—" : entry.chaosValue.toLocaleString("zh-TW")}</strong>
                <span>Chaos</span>
              </div>
              <Sparkline entry={entry} />
              <div className="market-facts">
                <span>成交量 <strong>{entry.volume.toLocaleString("zh-TW")}</strong></span>
                <span>庫存高點 <strong>{entry.stock.toLocaleString("zh-TW")}</strong></span>
                <span className={trend === null ? "" : trend >= 0 ? "up" : "down"}>
                  {trend === null ? "累積中" : <>{trend >= 0 ? <TrendingUp size={14} /> : <TrendingDown size={14} />}{trend.toFixed(1)}%</>}
                </span>
              </div>
              <a href={entry.officialTradeUrl} target="_blank" rel="noreferrer">到台服官方市集確認 <ExternalLink size={13} /></a>
            </article>
          );
        })}
      </section>
    </div>
  );
}
